SELECT  u.user_name,u.phone,u.head_img,u.age,o.* from  `order`  o, `user` u ,showtimes s


    u.id=o.user_id
    and
    s.id =o.showtimes_id

        and  u.user_name like concat('%',#{name},'%')


        and  o.user_id = #{userId}


        and  s.cinema_id=#{cinemaId}


        and  o.order_id=#{orderId}



limit  #{startIndex},#{size}

SELECT  count(0) from  `order`  o, `user` u ,showtimes s


    u.id=o.user_id
    and
    s.id =o.showtimes_id

        and  u.user_name like concat('%',#{name},'%')


        and  o.user_id = #{userId}


        and  s.cinema_id=#{cinemaId}


        and  o.order_id=#{orderId}
